SELECT COUNT(1)
  FROM adm_code_mst
 WHERE code_grp_cd = #{code_grp_cd}
   AND code_cd = #{code_cd}
   AND COALESCE(use_yn, 'Y') = 'Y'

   AND code_seq <> #{code_seq}

